import React, { useState } from "react";
import styled from "styled-components";
import { useNavigate } from "react-router-dom";
import SalonCard from "../../components/common/SalonCard";
import TabBar, { Tab } from "../../components/common/TabBar"; // import Tab type

const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 1280px;
  padding: 20px 0 60px;
`;

const WelcomeText = styled.h1`
  font-family: "Inter", sans-serif;
  font-size: 36px;
  font-weight: 700;
  color: #27374d;
  margin: 40px 0 20px;
`;

const PromoBanner = styled.div<{ image: string }>`
  width: 100%;
  height: 220px;
  border-radius: 12px;
  background-image: url(${(props) => props.image});
  background-size: cover;
  background-position: center;
  position: relative;
  overflow: hidden;
  margin-bottom: 40px;
`;

const BookNowButton = styled.button`
  position: absolute;
  bottom: 20px;
  left: 20px;
  background-color: #0b1c36;
  color: white;
  font-size: 16px;
  font-weight: 500;
  padding: 10px 18px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: 0.2s ease;
  &:hover {
    opacity: 0.9;
  }
`;

const SectionTitle = styled.h2`
  font-size: 22px;
  font-weight: 600;
  color: #2d2d2d;
  margin: 30px 0 16px;
`;

const HorizontalScroll = styled.div`
  display: flex;
  gap: 18px;
  overflow-x: auto;
  padding-bottom: 10px;
  &::-webkit-scrollbar {
    display: none;
  }
`;

const ScrollCircle = styled.div`
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: white;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
`;

const ArrowIcon = () => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="20"
    height="20"
    fill="none"
    stroke="#000"
    strokeWidth="2"
    viewBox="0 0 24 24"
  >
    <path d="M9 18l6-6-6-6" />
  </svg>
);

const HomePage: React.FC = () => {
  const navigate = useNavigate();

  // ✅ TabBar expects an array of { id, label }
  const tabs: Tab[] = [
    { id: "home", label: "Home" },
    { id: "bookings", label: "My Bookings" },
    { id: "profile", label: "My Profile" },
  ];

  const [activeTab, setActiveTab] = useState("home");

  const handleTabChange = (tabId: string) => {
    setActiveTab(tabId);
    if (tabId === "home") navigate("/homepage");
    if (tabId === "bookings") navigate("/my-bookings");
    if (tabId === "profile") navigate("/profile");
  };

  const salons = [
    {
      id: "hair-avenue",
      image: "/images/hairavenue.jpg",
      name: "Hair Avenue",
      distance: "2.3 km",
      location: "No 03, Kadalana Road, Kadalana, Moratuwa",
      rating: 4.7,
      reviews: 312,
    },
    {
      id: "blend-salon",
      image: "/images/blend.jpg",
      name: "Blend Salon",
      distance: "1.5 km",
      location: "45 Queen’s Street, Colombo",
      rating: 4.8,
      reviews: 280,
    },
  ];

  return (
    <PageWrapper>
      {/* ✅ Top navigation bar */}
      <TabBar tabs={tabs} activeTab={activeTab} onTabChange={handleTabChange} />

      <ContentWrapper>
        {/* ✅ Welcome Message */}
        <WelcomeText>Welcome Back, Enid!</WelcomeText>

        {/* ✅ Promotion banner */}
        <PromoBanner image="/images/promotionHeader.png">
          <BookNowButton>Book Now</BookNowButton>
        </PromoBanner>

        {/* ✅ Categories */}
        {["Trending Now", "Near You", "For Her", "For Him"].map((category) => (
          <div key={category}>
            <SectionTitle>{category}</SectionTitle>
            <HorizontalScroll>
              {salons.map((salon) => (
                <SalonCard
                  key={`${category}-${salon.id}`}
                  id={salon.id}
                  image={salon.image}
                  name={salon.name}
                  distance={salon.distance}
                  location={salon.location}
                  rating={salon.rating}
                  reviews={salon.reviews}
                  onClick={() =>
                    navigate(`/booking/${salon.id}`, { state: salon })
                  }
                />
              ))}
              <ScrollCircle>
                <ArrowIcon />
              </ScrollCircle>
            </HorizontalScroll>
          </div>
        ))}
      </ContentWrapper>
    </PageWrapper>
  );
};

export default HomePage;
